          "sourceLine": 8,
          "sourceRecord": 23,
          "gurmukhi": "ਨਾਮ ਤੁਲਿ ਕਛੁ ਅਵਰੁ ਨ ਹੋਇ ॥",
          "id": "sukhmani.a02.p08.l09",
          "unitId": "sukhmani.a02.p08",
