          "gurmukhi": "ਨਾਨਕ ਓਹੁ ਪੁਰਖੁ ਕਹੀਐ ਜੀਵਨ ਮੁਕਤਿ ॥੭॥",
          "id": "sukhmani.a09.p07.l10",
          "unitId": "sukhmani.a09.p07",
          "ashtpadi": 9,
          "kind": "pauri",
