          "gurmukhi": "ਨਾਨਕ ਜਾਨੈ ਸਚਾ ਸੋਇ ॥੭॥",
          "id": "sukhmani.a13.p07.l10",
          "unitId": "sukhmani.a13.p07",
          "ashtpadi": 13,
