          "sourceLine": 13,
          "sourceRecord": 39,
          "gurmukhi": "ਨਾਨਕ ਸੋ ਜਨੁ ਨਿਰਮਲੁ ਥੀਆ ॥੭॥",
          "id": "sukhmani.a15.p07.l10",
          "unitId": "sukhmani.a15.p07",
          "ashtpadi": 15,
          "kind": "pauri",
