          "gurmukhi": "ਕਰਤੇ ਕੀ ਮਿਤਿ ਨ ਜਾਨੈ ਕੀਆ ॥",
          "id": "sukhmani.a16.p07.l09",
          "unitId": "sukhmani.a16.p07",
          "ashtpadi": 16,
          "kind": "pauri",
          "pauri": 7,
